  const inWin = recent.filter(function (r) { const t = Date.parse(r.pushed_at || ''); return t >= lo && t <= hi; });
  let pick = inWin.filter(function (r) { const n = String(r.name).toLowerCase().replace(/[^a-z0-9]/g, ''); return push.tokens.some(function (t) { return n.indexOf(t) >= 0; }); });
