const plans = $('Plan Writes').all();
const ver = $('Verify Writes').all();
const res = $('Resolve INTERNAT').all();
const replies = $input.all();
const out = [];
for (let i = 0; i < plans.length; i++) {
  const p = plans[i].json; const v = ver[i].json; const r = res[i].json;
  const msgs = ((replies[i] && replies[i].json && replies[i].json.messages) || []).slice(1).map(function (m) { return String(m.text || ''); });
  const posted = msgs.join('\n');
  const send = [];
  if (p.ok) {
    const hasSummary = msgs.some(function (t) { return t.indexOf('browse/' + p.ticket + '|') >= 0 && /keys?/.test(t); });
    if (!hasSummary) {
      const lines = ['<https://futuremedia.atlassian.net/browse/' + p.ticket + '|' + p.ticket + '> – ' + p.summary];
      const n = p.key_ids.length + ' key' + (p.key_ids.length === 1 ? '' : 's');
      lines.push(v.ticket_tag_present ? n + ' – <https://app.lokalise.com/project/' + p.project_id + '/?view=multi&filter=tag_' + md5(p.ticket) + '|click to see>' : n);
      if (p.pr_url) { lines.push('PR <' + p.pr_url + '|#' + p.pr_number + '>'); }
      if (r.internat_key) { lines.push('Localization ticket <https://futuremedia.atlassian.net/browse/' + r.internat_key + '|' + r.internat_key + '>'); }
      else if (p.is_bug) { lines.push('Bug – no localization ticket (Localization label)'); }
      else { lines.push('Localization ticket requested (needs_localization added)'); }
      send.push(lines.join('\n'));
    }
  }
  const items = [];
  for (const w of p.keys_to_watch) {
    if (posted.indexOf('`' + w.key + '`') >= 0) { continue; }
    items.push('`' + w.key + '` "' + String(w.en || '').replace(/\n/g, ' ') + '" – ' + w.issue + (w.fix ? ' → ' + w.fix : ''));
  }
  if (!p.ok && p.key_ids.length) {
    const t = p.unconfirmed_tickets.length ? ' (listed in the push but not found in their commits: ' + p.unconfirmed_tickets.join(', ') + ')' : '';
    const line = p.key_ids.length + ' key' + (p.key_ids.length === 1 ? '' : 's') + ' not traced to a Jira ticket' + t + ' – no tags, descriptions or Jira updates; not ready';
    if (posted.indexOf(line) < 0) { items.push(line); }
  }
  if (items.length) { send.push('*⚠️ Keys to watch ⚠️*'); for (const it of items) { send.push(it); } }
  if (send.length) {
    const st = [];
    if (p.ok) {
      if (v.lok_error) { st.push('⚠️ Lokalise writes failed – keys left unchanged'); }
      st.push(v.desc_added ? '🔹 Key descriptions added (' + v.desc_added + ')' : '⚠️ No key descriptions added');
      const missing = p.no_desc.length + (v.desc_planned - v.desc_added);
      if (missing > 0) { st.push('⚠️ No description added for ' + missing + ' key' + (missing === 1 ? '' : 's') + ' – review needed'); }
      st.push(v.shots_added ? '🔹 Screenshots added (' + v.shots_added + ')' : '⚠️ No screenshots added – add manually if needed');
      if (!missing && !v.lok_error) { st.push('🔹 Ready to populate and review'); }
    } else {
      st.push('⚠️ No Jira ticket confirmed – nothing written to Lokalise or Jira');
    }
    if (p.llm_error) { st.push('⚠️ Context step failed – descriptions and checks may be missing'); }
    send.push('```' + st.join('\n') + '```');
  }
  for (const t of send) { out.push({ json: { channel: p.channel, thread_ts: p.ts, text: t } }); }
}
return out;
